@pytest.fixture(autouse=True)
def clear_database():
    api.packages.clear()
    api.missions.clear()


@pytest.mark.parametrize(
    "level, source, expected",
    CASES,
    ids=[f"level_{level:02d}" for level, _, _ in CASES],
)
def test_level(level, source, expected):
    output = io.StringIO()
    with redirect_stdout(output):
        exec(compile(source, f"level_{level:02d}", "exec"), api.__dict__)
    assert output.getvalue().strip() == expected
